import React from 'react';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { Toaster } from 'react-hot-toast';
import { AuthProvider, useAuth } from './context/AuthContext';
import { PermissionsProvider, usePermissions } from './context/PermissionsContext';
import { GoogleOAuthProvider } from '@react-oauth/google';

// Auth pages
import LandingPage        from './pages/LandingPage';
import LoginPage          from './pages/auth/LoginPage';
import RegisterPage       from './pages/auth/RegisterPage';
import OTPVerifyPage      from './pages/auth/OTPPage';
import ForgotPasswordPage from './pages/auth/ForgotPasswordPage';
import ResetPasswordPage  from './pages/auth/ResetPasswordPage';

// App pages
import DashboardPage      from './pages/dashboard/DashboardPage';
import ProjectsPage       from './pages/projects/ProjectsPage';
import CreateProjectPage  from './pages/projects/CreateProjectPage';
import ProjectDetailPage  from './pages/projects/ProjectDetailPage';
import DailyReportFormPage from './pages/projects/Dailyreportformpage';
import ContractUploadPage from './pages/contracts/ContractUploadPage';
import ContractDetailPage from './pages/contracts/ContractDetailPage';
import TeamPage           from './pages/team/TeamPage';
import CompaniesPage      from './pages/owner/CompaniesPage';

function Spinner() {
  return (
    <div style={{ display:'flex', minHeight:'100vh', alignItems:'center', justifyContent:'center', background:'#0D0D1A' }}>
      <div style={{ width:36, height:36, border:'3px solid #F59E0B', borderTopColor:'transparent', borderRadius:'50%', animation:'spin 1s linear infinite' }}/>
      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>
    </div>
  );
}

function PrivateRoute({ children, module, roles }) {
  const { user, loading } = useAuth();
  const { can, role } = usePermissions();
  if (loading) return <Spinner/>;
  if (!user) return <Navigate to="/login" replace/>;
  if (roles && !roles.includes(role)) return <AccessDenied/>;
  if (module && !can(module)) return <AccessDenied/>;
  return children;
}

function PublicRoute({ children }) {
  const { user, loading } = useAuth();
  if (loading) return null;
  return user ? <Navigate to="/dashboard" replace/> : children;
}

function AccessDenied() {
  return (
    <div style={{ display:'flex', minHeight:'100vh', alignItems:'center', justifyContent:'center', background:'#0D0D1A', flexDirection:'column', gap:16 }}>
      <div style={{ fontSize:48 }}>🔒</div>
      <h2 style={{ color:'#fff', fontSize:24, margin:0 }}>Accès restreint</h2>
      <p style={{ color:'#6B7280', fontSize:15, margin:0 }}>Vous n'avez pas les droits pour accéder à cette section.</p>
      <button onClick={()=>window.history.back()} style={{ padding:'10px 24px', borderRadius:8, background:'rgba(245,158,11,0.1)', border:'1px solid rgba(245,158,11,0.3)', color:'#F59E0B', cursor:'pointer', fontSize:14 }}>← Retour</button>
    </div>
  );
}

function ComingSoon({ title, icon, phase=2 }) {
  return (
    <div style={{ display:'flex', minHeight:'80vh', alignItems:'center', justifyContent:'center', flexDirection:'column', gap:16 }}>
      <div style={{ fontSize:56 }}>{icon}</div>
      <h2 style={{ color:'#fff', fontSize:24, margin:0 }}>{title}</h2>
      <p style={{ color:'#6B7280', fontSize:15, margin:0 }}>Ce module sera disponible en Phase {phase}.</p>
      <span style={{ padding:'4px 14px', borderRadius:100, background:'rgba(245,158,11,0.1)', border:'1px solid rgba(245,158,11,0.3)', color:'#F59E0B', fontSize:12, fontWeight:600 }}>En développement</span>
    </div>
  );
}

function AppRoutes() {
  return (
    <Routes>
      {/* Public */}
      <Route path="/"                element={<LandingPage/>}/>
      <Route path="/login"           element={<PublicRoute><LoginPage/></PublicRoute>}/>
      <Route path="/register"        element={<PublicRoute><RegisterPage/></PublicRoute>}/>
      <Route path="/verify-otp"      element={<PublicRoute><OTPVerifyPage/></PublicRoute>}/>
      <Route path="/forgot-password" element={<PublicRoute><ForgotPasswordPage/></PublicRoute>}/>
      <Route path="/reset-password"  element={<PublicRoute><ResetPasswordPage/></PublicRoute>}/>

      {/* Dashboard — all roles */}
      <Route path="/dashboard" element={<PrivateRoute><DashboardPage/></PrivateRoute>}/>

      {/* Projects */}
      <Route path="/projects"      element={<PrivateRoute><ProjectsPage/></PrivateRoute>}/>
      <Route path="/projects/new"  element={<PrivateRoute roles={['admin_entreprise','office_admin']}><CreateProjectPage/></PrivateRoute>}/>
      <Route path="/projects/:id"  element={<PrivateRoute><ProjectDetailPage/></PrivateRoute>}/>

      {/* Daily Reports */}
      <Route path="/projects/:id/reports/new"         element={<PrivateRoute module="journal"><DailyReportFormPage/></PrivateRoute>}/>
      <Route path="/projects/:id/reports/:reportId"   element={<PrivateRoute module="journal"><DailyReportFormPage/></PrivateRoute>}/>

      {/* Contracts */}
      <Route path="/contracts/upload" element={<PrivateRoute><ContractUploadPage/></PrivateRoute>}/>
      <Route path="/contracts/:id"    element={<PrivateRoute><ContractDetailPage/></PrivateRoute>}/>

      {/* Team — B and C */}
      <Route path="/team"    element={<PrivateRoute roles={['app_owner','admin_entreprise','office_admin']}><TeamPage/></PrivateRoute>}/>
      <Route path="/workers" element={<PrivateRoute roles={['app_owner','admin_entreprise','office_admin']}><TeamPage/></PrivateRoute>}/>

      {/* Companies — App Owner only */}
      <Route path="/companies" element={<PrivateRoute roles={['app_owner']}><CompaniesPage/></PrivateRoute>}/>

      {/* Attendance — E and F */}
      <Route path="/pointage" element={<PrivateRoute roles={['app_owner','chef_chantier','chef_equipe']}><ComingSoon title="Pointage GPS" icon="📍" phase={1}/></PrivateRoute>}/>

      {/* Module stubs */}
      <Route path="/planning"  element={<PrivateRoute module="planning"><ComingSoon title="Planning / Gantt" icon="📅"/></PrivateRoute>}/>
      <Route path="/budget"    element={<PrivateRoute module="budget"><ComingSoon title="Budget & Achats" icon="💰"/></PrivateRoute>}/>
      <Route path="/qhse"      element={<PrivateRoute module="qhse"><ComingSoon title="QHSE / Sécurité" icon="🛡️"/></PrivateRoute>}/>
      <Route path="/documents" element={<PrivateRoute module="documents"><ComingSoon title="Documents & Plans" icon="📁"/></PrivateRoute>}/>
      <Route path="/stock"     element={<PrivateRoute module="stock"><ComingSoon title="Stocks & Livraisons" icon="📦"/></PrivateRoute>}/>
      <Route path="/treasury"  element={<PrivateRoute module="treasury"><ComingSoon title="Trésorerie" icon="🏦"/></PrivateRoute>}/>
      <Route path="/reports"   element={<PrivateRoute module="reports"><ComingSoon title="Rapports" icon="📈"/></PrivateRoute>}/>
      <Route path="/journal"   element={<PrivateRoute module="journal"><ComingSoon title="Journal terrain" icon="📓"/></PrivateRoute>}/>
      <Route path="/settings"  element={<PrivateRoute roles={['app_owner']}><ComingSoon title="Paramètres système" icon="⚙️"/></PrivateRoute>}/>

      <Route path="*" element={<Navigate to="/" replace/>}/>
    </Routes>
  );
}

export default function App() {
  const GOOGLE_CLIENT_ID = process.env.REACT_APP_GOOGLE_CLIENT_ID || '';
  const app = (
    <AuthProvider>
      <PermissionsProvider>
        <BrowserRouter>
          <Toaster position="top-right" toastOptions={{ style:{ background:'#1A1A2E', color:'#fff', border:'1px solid rgba(245,158,11,0.2)', fontSize:14 }, success:{ iconTheme:{ primary:'#10B981', secondary:'#fff' } }, error:{ iconTheme:{ primary:'#EF4444', secondary:'#fff' } } }}/>
          <AppRoutes/>
        </BrowserRouter>
      </PermissionsProvider>
    </AuthProvider>
  );
  return GOOGLE_CLIENT_ID ? <GoogleOAuthProvider clientId={GOOGLE_CLIENT_ID}>{app}</GoogleOAuthProvider> : app;
}
